type BatchInferenceNamespace struct {
	config ClientConfig
}

func NewBatchInferenceNamespace(config ClientConfig) *BatchInferenceNamespace {
	return &BatchInferenceNamespace{
		config: config,
	}
}

// InferenceCreateBatchFile creates a file record and returns a `file_id` plus a short-lived presigned `PUT` URL (typically valid for ~15 minutes). Upload the raw JSONL bytes to `upload_url` (see `PUT /{upload_path}`) before calling `POST /v1/batches`.
//
// Parameters:
//
//	fileName: The file you plan to upload. Must end with `.jsonl`
//	(case-insensitive) and contain one request per line in the schema expected
//	by the target `provider`.
func (sdk *BatchInferenceNamespace) InferenceCreateBatchFile(ctx context.Context, params InferenceCreateBatchFileParams, opts ...RequestOption) (*BatchFileCreateResponse, error) {
	return InferenceCreateBatchFile(ctx, sdk.config, params, opts...)
}

// InferenceUploadBatchFile uploads raw JSONL bytes to the presigned URL returned by `POST /v1/batches/files`. Use the returned `upload_url` verbatim and send the bytes as `application/octet-stream` or omit `Content-Type` to avoid signature mismatches. The upload must complete before `POST /v1/batches` checks the object with a `HEAD` request.
//
// Uploads the raw JSONL bytes to the presigned `upload_url` returned by `POST /v1/batches/files`. **The URL is dynamic — do not construct it.** Use the `upload_url` value from the previous step verbatim. Its host, path, and query parameters are part of the short-lived (~15 minute) signature and change per request; the server and path shown here are illustrative. If the URL expires before the upload completes, create a new file intent and retry. `POST /v1/batches` performs a `HEAD` check on the uploaded object and will reject the batch if this upload has not completed. Send the raw JSONL bytes verbatim. Presigned PUT URLs are signature-sensitive to request headers — prefer `application/octet-stream` or omit `Content-Type` entirely. A custom value (for example `application/jsonl`) can cause signature mismatches unless the URL was signed for that exact header.
func (sdk *BatchInferenceNamespace) InferenceUploadBatchFile(ctx context.Context, params InferenceUploadBatchFileParams, opts ...RequestOption) (any, error) {
	return InferenceUploadBatchFile(ctx, sdk.config, params, opts...)
}

// InferenceCreateBatch submits a batch job against a previously uploaded JSONL input file. The upload must have completed before this call; otherwise the request is rejected. Supply a unique `request_id` to make the submission idempotent — retries with the same value return the existing job. When `provider` is `openai`, the `url` on each JSONL line must match `endpoint`.
//
// Parameters:
//
//	fileId: The `file_id` returned by `POST /v1/batches/files`.
//	provider: The inference provider whose JSONL schema the input file conforms
//	to. `openai` follows the OpenAI Batch API input schema (`custom_id`,
//	`method`, `url`, `body`); `anthropic` follows the Anthropic Message Batches
//	JSONL conventions.
//	completionWindow: Time window in which the job must complete. Jobs that do
//	not finish in time transition to `expired`.
//	requestId: Client-supplied idempotency key. Retries with the same value
//	return the existing job instead of creating a duplicate.
//	endpoint: Inference endpoint each request is dispatched to. **Required when
//	`provider` is `openai` and must match the `url` on every JSONL line. Must be
//	omitted when `provider` is `anthropic`.**
//	metadata: Optional string-valued metadata to attach to the job.
func (sdk *BatchInferenceNamespace) InferenceCreateBatch(ctx context.Context, params InferenceCreateBatchParams, opts ...RequestOption) (*Batch, error) {
	return InferenceCreateBatch(ctx, sdk.config, params, opts...)
}

// InferenceListBatches returns a cursor-paginated list of batch jobs, ordered newest first. Use `limit` to control page size and `after` to page forward using the `last_id` from the previous response.
//
// Parameters:
//
//	after: Cursor for pagination. Pass the `last_id` value from the previous
//	response to fetch the next page. Omit for the first page.
//	limit: Maximum number of batches to return per page.
//	status: Optional filter restricting results to batches in the given
//	lifecycle state.
func (sdk *BatchInferenceNamespace) InferenceListBatches(ctx context.Context, params InferenceListBatchesParams, opts ...RequestOption) (*BatchListResponse, error) {
	return InferenceListBatches(ctx, sdk.config, params, opts...)
}

// InferenceListBatchesPaginated returns a cursor-paginated list of batch jobs, ordered newest first. Use `limit` to control page size and `after` to page forward using the `last_id` from the previous response.
//
// Parameters:
//
//	after: Cursor for pagination. Pass the `last_id` value from the previous
//	response to fetch the next page. Omit for the first page.
