// InferenceGetBatch returns the current state of a batch job. Poll until `status` reaches a terminal value (`completed`, `failed`, `expired`, or `cancelled`).
//
// Parameters:
//
//	batchId: The batch job identifier.
func (sdk *BatchInferenceNamespace) InferenceGetBatch(ctx context.Context, params InferenceGetBatchParams, opts ...RequestOption) (*Batch, error) {
	return InferenceGetBatch(ctx, sdk.config, params, opts...)
}

// InferenceGetBatchResults returns short-lived presigned download URLs for the output (and optional error sidecar) of a completed batch job. If results are not yet ready, the response sets `result_available: false` or returns `412 Precondition Failed`; in both cases, keep polling batch status and retry. Download the artifacts soon after fetching — the URLs are short-lived. Result files themselves are retained for up to 30 days after the job completes, after which they are deleted.
//
// Parameters:
//
//	batchId: The batch job identifier.
func (sdk *BatchInferenceNamespace) InferenceGetBatchResults(ctx context.Context, params InferenceGetBatchResultsParams, opts ...RequestOption) (*BatchResultsResponse, error) {
	return InferenceGetBatchResults(ctx, sdk.config, params, opts...)
}

// InferenceCancelBatch requests cancellation of a batch job. The job transitions to `cancelling` and, once in-flight requests drain, to `cancelled`. Jobs already in a terminal state (`completed`, `failed`, `expired`, `cancelled`) cannot be cancelled and return `409 Conflict`. Cancellation is also rejected with `409 Conflict` while the job has not yet been submitted to the upstream provider — there is nothing to cancel until the provider batch id is assigned. Partial results produced before cancellation remain available via `GET /v1/batches/{batch_id}/results`.
//
// Parameters:
//
//	batchId: The batch job identifier.
func (sdk *BatchInferenceNamespace) InferenceCancelBatch(ctx context.Context, params InferenceCancelBatchParams, opts ...RequestOption) (*Batch, error) {
	return InferenceCancelBatch(ctx, sdk.config, params, opts...)
}
